def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Extend each diagonal run of two or more identical non-background cells
    # in both directions, stopping at the edge or any non-background cell.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                nr, nc = r+dr, c+dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                er, ec = r, c
                while 0 <= er+dr < h and 0 <= ec+dc < w and grid[er+dr][ec+dc] == color:
                    er, ec = er+dr, ec+dc
                # Extend beyond both ends; use the original grid for obstruction checks.
                rr, cc = r-dr, c-dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                    rr, cc = rr-dr, cc-dc
                rr, cc = er+dr, ec+dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                    rr, cc = rr+dr, cc+dc
    return out

